insert into route_briefs (title, description, start_location, end_location, waypoints, maps_url, notes) values
('Singapore City Highlights Loop','Cruise arrival city loop: Marina Bay Cruise Centre → Gardens by the Bay → Merlion Park → Raffles Hotel → Chinatown Heritage Centre → return.','Marina Bay Cruise Centre Singapore, 61 Marina Coastal Dr, Singapore 018947','Marina Bay Cruise Centre Singapore, 61 Marina Coastal Dr, Singapore 018947','["Gardens by the Bay, 18 Marina Gardens Dr, Singapore 018953","Merlion Park, 1 Fullerton Rd, Singapore 049213","Raffles Singapore, 1 Beach Rd, Singapore 189673","Chinatown Heritage Centre, 48 Pagoda St, Singapore 059207"]'::jsonb,'https://www.google.com/maps/dir/Marina+Bay+Cruise+Centre+Singapore,+61+Marina+Coastal+Dr,+Singapore+018947/Gardens+by+the+Bay,+18+Marina+Gardens+Dr,+Singapore+018953/Merlion+Park,+1+Fullerton+Rd,+Singapore+049213/Raffles+Singapore,+1+Beach+Rd,+Singapore+189673/Chinatown+Heritage+Centre,+48+Pagoda+St,+Singapore+059207/Marina+Bay+Cruise+Centre+Singapore,+61+Marina+Coastal+Dr,+Singapore+018947/@1.2757712,103.8234828,13.4z/data=!3m1!5s0x31da19734845e93f:0x81f2323dbcc673cd!4m38!4m37!1m5!1m1!1s0x31da1900758262cb:0x36ec1640ec829d0c!2m2!1d103.8602571!2d1.2667383!1m5!1m1!1s0x31da1904937e1633:0x62099677b59fca76!2m2!1d103.8636132!2d1.2815683!1m5!1m1!1s0x31da190ed6203605:0x66ad5eee6e01f3a7!2m2!1d103.8543872!2d1.2867449!1m5!1m1!1s0x31da19a5bbca44c1:0x647f3845b65cdec2!2m2!1d103.854483!2d1.294889!1m5!1m1!1s0x31da1973493ae8dd:0x26539d86b7ad1b0b!2m2!1d103.8442036!2d1.2835298!1m5!1m1!1s0x31da1900758262cb:0x36ec1640ec829d0c!2m2!1d103.8602571!2d1.2667383!3e0?entry=ttu&g_ep=EgoyMDI2MDMwOS4wIKXMDSoASAFQAw%3D%3D','Allow 10-15 minutes between stops for group movement. Use Raffles Hotel drop-off point for coach parking.');
insert into audio_pois (id, name, lat, lng, radius_m, messages, tags) values
  ('00000000-0000-0000-0000-00000000a001', 'Marina Bay Cruise Centre', 1.2667383, 103.8602571, 200, '{"ko-KR":"마리나 베이 크루즈 센터입니다. 수하물은 1층 드롭존에서 내리시고, 2층 체크인 카운터로 이동하세요.","en-US":"You are approaching Marina Bay Cruise Centre. Drop luggage on level 1, then proceed to level 2 check-in.","ja-JP":"マリーナベイクルーズセンターです。1階で荷物を降ろし、2階のチェックインへお進みください。"}', '{"singapore","cruise"}'),
  ('00000000-0000-0000-0000-00000000a002', 'Gardens by the Bay', 1.2815683, 103.8636132, 180, '{"ko-KR":"가든스 바이 더 베이에 도착했습니다. 플라워 돔과 클라우드 포레스트 입구가 앞에 있습니다.","en-US":"Welcome to Gardens by the Bay. Flower Dome and Cloud Forest entrances are ahead.","ja-JP":"ガーデンズ・バイ・ザ・ベイに到着しました。フラワードームとクラウドフォレストの入口があります。"}', '{"singapore","garden"}'),
  ('00000000-0000-0000-0000-00000000a003', 'Merlion Park', 1.2867449, 103.8543872, 150, '{"ko-KR":"멀라이언 파크입니다. 단체 사진 포인트는 분수 정면 좌측 데크입니다.","en-US":"Merlion Park ahead. Best group photo spot is on the left deck facing the fountain.","ja-JP":"マーライオンパークです。噴水を正面にして左側デッキが写真スポットです。"}', '{"singapore","iconic"}'),
  ('00000000-0000-0000-0000-00000000a004', 'Raffles Hotel', 1.294889, 103.854483, 120, '{"ko-KR":"래플스 호텔입니다. 체크인 로비는 메인 아치 안쪽에 있습니다.","en-US":"Arriving at Raffles Hotel. Check-in lobby is through the main arch.","ja-JP":"ラッフルズホテル到着。チェックインロビーはメインアーチの奥です。"}', '{"singapore","hotel"}'),
  ('00000000-0000-0000-0000-00000000a005', 'Chinatown Heritage Centre', 1.2835298, 103.8442036, 150, '{"ko-KR":"차이나타운 헤리티지 센터입니다. 투어 동선은 2층 전시부터 시작하세요.","en-US":"Chinatown Heritage Centre. Start the group on level 2 exhibits.","ja-JP":"チャイナタウン・ヘリテージセンターです。2階展示からご案内ください。"}', '{"singapore","museum"}');
